-- V34: pembatasan.id tidak lagi memakai identity.
--
-- V28 (hasil pg_dump) masih membawa `GENERATED BY DEFAULT AS IDENTITY` untuk
-- pembatasan.id, sedangkan seluruh tabel lain di skema v2 memakai id yang
-- di-assign aplikasi (IdGenerator). Karena seeder mengisi id eksplisit (1..3),
-- sequence identity tetap di posisi awal sehingga INSERT baru dari aplikasi
-- memakai id=1 → "duplicate key value violates unique constraint
-- pembatasan_pkey" (HTTP 409 saat admin memblokir menu/kategori siswa).
--
-- Entitas Pembatasan kini memakai pola yang sama dengan entitas lain
-- (Persistable + IdGenerator), jadi default identity dihapus agar konsisten.

ALTER TABLE public.pembatasan ALTER COLUMN id DROP IDENTITY IF EXISTS;
